INSERT INTO setting_template_refs(tenant_id,id,subject,kind,template_key,entity_id) SELECT t.tenant_id,'tref_'||lower(hex(randomblob(12))),'music_exam','courses','c_6430edb73b7d',t.id FROM offer_courses t JOIN tenant_subjects s ON s.tenant_id=t.tenant_id AND s.id=t.subject WHERE t.subject='music_exam' AND t.source='template' AND t.version=1 AND t.name='器乐主项' AND s.pack_version='0.1';
